import { AvailabilityCalendar } from "@/components/AvailabilityCalendar";

export default function Page() {
  return <AvailabilityCalendar />;
}

"use client";

import { useMemo, useState } from "react";

const initialRecords = [
  {
    "id": "booking-1",
    "label": "SlotWise 423 queue item",
    "value": "1269 open",
    "status": "Queued",
    "meta": "Variant 423 command queue"
  },
  {
    "id": "booking-2",
    "label": "SlotWise 423 rule set",
    "value": "427 rules",
    "status": "Active",
    "meta": "Variant 423 rule builder",
    "parentId": "booking-1"
  },
  {
    "id": "booking-3",
    "label": "SlotWise 423 insight",
    "value": "513%",
    "status": "Healthy",
    "meta": "Variant 423 event timeline",
    "parentId": "booking-1"
  }
];
const views = ["Command","Queue","Rules","Insights"];
const transitions = ["Requested","Confirmed","Completed"];

export function AvailabilityCalendar({ initialView = views[0] }: { initialView?: string }) {
  const [view, setView] = useState(initialView);
  const [records, setRecords] = useState(initialRecords);
  const [input, setInput] = useState("");
  const [events, setEvents] = useState<string[]>(["SlotWise 423 ready"]);
  const visible = useMemo(() => records.filter((record) => view === views[0] || record.status.toLowerCase().includes(view.toLowerCase()) || record.meta.toLowerCase().includes(view.toLowerCase())), [records, view]);
  async function mutate(payload: { action: "create" | "transition" | "delete"; id?: string; label?: string; value?: string; status?: string }) {
    const response = await fetch("/api/bookings", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (!response.ok) {
      setEvents((current) => ["Backend mutation failed", ...current]);
      return;
    }
    const data = await response.json() as { records: typeof initialRecords; record?: (typeof initialRecords)[number] };
    setRecords(data.records);
    setEvents((current) => [payload.action + " persisted through /api/bookings", ...current]);
    if (payload.action === "create") setInput("");
  }
  return (
    <main className="app">
      <header className="top"><div className="wrap" style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"center"}}><strong>SlotWise 423</strong><nav style={{display:"flex",gap:8,overflowX:"auto"}}>{views.map((item) => <a key={item} href={"#"+item} onClick={(event) => { event.preventDefault(); setView(item); }} className="primary" style={{background:item===view?"var(--primary)":"#e2e8f0",color:item===view?"white":"#0f172a",textDecoration:"none"}}>{item}</a>)}</nav></div></header>
      <section className="wrap hero">
        <div className="panel">
          <p style={{fontWeight:900,textTransform:"uppercase",letterSpacing:".16em",fontSize:12,color:"var(--primary)"}}>booking</p>
          <h1 style={{fontSize:48,lineHeight:1,margin:"10px 0"}}>SlotWise 423</h1>
          <p style={{lineHeight:1.7,color:"#475569"}}>Build a project Gantt planning app for project managers, contributors, and executives. Real users: project manager, contributor, executive. Real actions: create tasks, define dependency graph, calculate dates, render Gantt timeline, drag tasks to reschedule, update dependent milestones, and export plan. Real data: users, projects, tasks, dependencies, milestones, schedule changes. Real state changes: dependency edits recalculate schedule, dragging changes task dates, milestone status persists, refresh keeps saved state. unique architecture variant 423</p>
          <div className="calendar-grid" style={{marginTop:18}}>{visible.map((record) => <article key={record.id || record.label} className="card"><strong>{record.label}</strong><p style={{fontSize:28,fontWeight:850,margin:"8px 0"}}>{record.value}</p><span>{record.status}</span><div style={{display:"flex",gap:8,marginTop:12}}><button data-action="transition" data-api="/api/bookings" data-db-change="update-status" data-state-update="setRecords" data-ui-refresh="records-list" onClick={() => mutate({ action: "transition", id: record.id })} className="primary" style={{padding:"8px 10px"}}>Advance variant 423 state</button><button data-action="delete" data-api="/api/bookings" data-db-change="delete-record" data-state-update="setRecords" data-ui-refresh="records-list" onClick={() => mutate({ action: "delete", id: record.id })} className="primary" style={{padding:"8px 10px",background:"#fee2e2",color:"#991b1b"}}>Remove variant 423 audit</button></div></article>)}</div>
        </div>
        <aside className="panel">
          <h2>Create booking event</h2>
          <p>Adds variant 423 event to isolated runtime</p>
          <textarea value={input} onChange={(event) => setInput(event.target.value)} placeholder="Name, Owner, State, Score" style={{width:"100%",minHeight:110,border:"1px solid #cbd5e1",borderRadius:12,padding:12}} />
          <button data-action="create" data-api="/api/bookings" data-db-change="insert-record" data-state-update="setRecords" data-ui-refresh="records-list" onClick={() => mutate({ action: "create", label: input || "Create booking event", value: "New", status: transitions[0] || "Created" })} className="primary" style={{width:"100%",marginTop:10}}>book slot</button>
          <div style={{display:"grid",gap:8,marginTop:16}}>{events.map((event) => <div key={event} className="card">{event}</div>)}</div>
        </aside>
      </section>
    </main>
  );
}

export const interactionMap = [
  {
    "label": "Create variant 423 event",
    "type": "create",
    "target": "BookingEvent423",
    "result": "Adds event to SlotWise 423 runtime queue"
  },
  {
    "label": "Advance variant 423 state",
    "type": "transition",
    "target": "BookingRuntime423",
    "result": "Moves Queued -> Active -> Reviewed -> Done"
  },
  {
    "label": "Remove variant 423 audit",
    "type": "delete",
    "target": "BookingAudit423",
    "result": "Removes audit and dependent runtime rows"
  }
] as const;
export const relationshipMap = [
  {
    "from": "BookingRuntime423",
    "to": "BookingEvent423",
    "type": "one-to-many",
    "via": "booking-423RecordId"
  },
  {
    "from": "BookingEvent423",
    "to": "BookingAudit423",
    "type": "one-to-many",
    "via": "booking-423EventId"
  }
] as const;

export function validateBookingsRelationships(record: { parentId?: string }, existingIds: string[]) {
  if (!relationshipMap.length) throw new Error("Generated app requires relational data models.");
  return !record.parentId || existingIds.includes(record.parentId);
}

export const models = [
  {
    "name": "BookingRuntime423",
    "fields": [
      "booking-423Name",
      "booking-423Owner",
      "booking-423State",
      "booking-423Score"
    ]
  },
  {
    "name": "BookingEvent423",
    "fields": [
      "booking-423RecordId",
      "booking-423Action",
      "booking-423Actor",
      "booking-423Result"
    ]
  },
  {
    "name": "BookingAudit423",
    "fields": [
      "booking-423EventId",
      "booking-423Reviewer",
      "booking-423Decision",
      "booking-423CreatedAt"
    ]
  }
] as const;
export const relationships = [
  {
    "from": "BookingRuntime423",
    "to": "BookingEvent423",
    "type": "one-to-many",
    "via": "booking-423RecordId"
  },
  {
    "from": "BookingEvent423",
    "to": "BookingAudit423",
    "type": "one-to-many",
    "via": "booking-423EventId"
  }
] as const;

export function assertRelationalSchema() {
  if (relationships.length < 2) throw new Error("Relational schema is required.");
  return relationships.map((relation) => relation.from + " -> " + relation.to);
}

import { applyBookingsMutation, removeBookingsRecord, transitionBookingsRecord } from "@/lib/availability-engine";

export const statusFlow = [
  "Requested",
  "Confirmed",
  "Completed"
] as const;

export function handleBookingsAction(records: Array<{ id: string; label: string; value: string; status: string; meta?: string; parentId?: string }>, body: { action?: string; id?: string; label?: string; value?: string; status?: string }) {
  if (body.action === "transition" && body.id) return transitionBookingsRecord(records, body.id, [...statusFlow]);
  if (body.action === "delete" && body.id) return removeBookingsRecord(records, body.id);
  return applyBookingsMutation(records, { label: body.label || "Create booking event", value: body.value || "New", status: body.status || statusFlow[0] || "Created" });
}

